<?php require_once 'config/db.php';require_once 'includes/auth.php';require_login();$r=$_SESSION['user']['role'];$products=$conn->query('SELECT COUNT(*) c FROM products')->fetch_assoc()['c'];$orders=$conn->query('SELECT COUNT(*) c FROM orders')->fetch_assoc()['c'];$customers=$conn->query("SELECT COUNT(*) c FROM users WHERE role='customer'")->fetch_assoc()['c'];$revenue=$conn->query("SELECT COALESCE(SUM(total),0) c FROM orders WHERE status NOT IN ('Cancelled','Rejected')")->fetch_assoc()['c'];include 'includes/header.php';?><div class="hero"><h1>Order Management System</h1><p>Customer cart, order confirmation, payment choice, shipping tracking and role-based staff access.</p><p>Welcome, <b><?=h($_SESSION['user']['name'])?></b> (<?=h($r)?>).</p></div><?php if($r!=='customer'):?><div class="grid"><div class="card">Products<div class="stat"><?=$products?></div></div><div class="card">Orders<div class="stat"><?=$orders?></div></div><div class="card">Customers<div class="stat"><?=$customers?></div></div><div class="card">Order Value<div class="stat">₹<?=number_format($revenue,2)?></div></div></div><?php endif;?><div class="card"><h2>Quick Actions</h2><div class="actions"><a class="btn" href="products.php">Browse Products</a><?php if($r==='customer'):?><a class="btn" href="cart.php">View Cart</a><?php endif;?><a class="btn" href="orders.php">View Orders / Status</a><?php if(in_array($r,['admin','sales'])):?><a class="btn" href="customers.php">Customers</a><?php endif;?><?php if($r==='admin'):?><a class="btn" href="users.php">Staff & Permissions</a><?php endif;?><?php if(in_array($r,['admin','report_staff'])):?><a class="btn" href="reports.php">Reports</a><?php endif;?></div></div><?php include 'includes/footer.php';?>